CREATE TABLE public.resume_catalogue_sources (id text PRIMARY KEY, label text NOT NULL, version text NOT NULL, source_url text NOT NULL, license text NOT NULL, attribution text NOT NULL, modifications text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.resume_catalogue_sources TO authenticated; GRANT ALL ON public.resume_catalogue_sources TO service_role;
ALTER TABLE public.resume_catalogue_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_catalogue_sources FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_industries (id text PRIMARY KEY, label text NOT NULL, sort_order integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.resume_industries TO authenticated; GRANT ALL ON public.resume_industries TO service_role;
ALTER TABLE public.resume_industries ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_industries FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_categories (id text PRIMARY KEY, industry_id text NOT NULL REFERENCES public.resume_industries(id), label text NOT NULL, published boolean NOT NULL DEFAULT true, UNIQUE(industry_id,label));
GRANT SELECT ON public.resume_categories TO authenticated; GRANT ALL ON public.resume_categories TO service_role;
ALTER TABLE public.resume_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_categories FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_role_blueprints (id text PRIMARY KEY, label text NOT NULL, version integer NOT NULL DEFAULT 1, definition jsonb NOT NULL, published boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.resume_role_blueprints TO authenticated; GRANT ALL ON public.resume_role_blueprints TO service_role;
ALTER TABLE public.resume_role_blueprints ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_role_blueprints FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_occupations (id text PRIMARY KEY, title text NOT NULL, source_id text REFERENCES public.resume_catalogue_sources(id), source_code text, blueprint_id text NOT NULL REFERENCES public.resume_role_blueprints(id), published boolean NOT NULL DEFAULT true, published_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,source_code));
GRANT SELECT ON public.resume_occupations TO authenticated; GRANT ALL ON public.resume_occupations TO service_role;
ALTER TABLE public.resume_occupations ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_occupations FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_occupation_categories (occupation_id text REFERENCES public.resume_occupations(id) NOT NULL, category_id text REFERENCES public.resume_categories(id) NOT NULL, PRIMARY KEY(occupation_id,category_id));
GRANT SELECT ON public.resume_occupation_categories TO authenticated; GRANT ALL ON public.resume_occupation_categories TO service_role;
ALTER TABLE public.resume_occupation_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_occupation_categories FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.resume_occupations o WHERE o.id=occupation_id AND o.published));
CREATE TABLE public.resume_job_titles (id text PRIMARY KEY, occupation_id text NOT NULL REFERENCES public.resume_occupations(id), title text NOT NULL, normalized_title text NOT NULL UNIQUE, category_id text NOT NULL REFERENCES public.resume_categories(id), industry_id text NOT NULL REFERENCES public.resume_industries(id), popular_rank integer, published boolean NOT NULL DEFAULT true, published_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.resume_job_titles TO authenticated; GRANT ALL ON public.resume_job_titles TO service_role;
ALTER TABLE public.resume_job_titles ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_job_titles FOR SELECT TO authenticated USING (published);
CREATE INDEX resume_titles_search ON public.resume_job_titles USING gin(to_tsvector('simple',title));
CREATE INDEX resume_titles_filters ON public.resume_job_titles(industry_id,category_id);
CREATE TABLE public.resume_title_aliases (title_id text NOT NULL REFERENCES public.resume_job_titles(id), alias text NOT NULL, normalized_alias text NOT NULL, PRIMARY KEY(title_id,normalized_alias));
GRANT SELECT ON public.resume_title_aliases TO authenticated; GRANT ALL ON public.resume_title_aliases TO service_role;
ALTER TABLE public.resume_title_aliases ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_title_aliases FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.resume_job_titles t WHERE t.id=title_id AND t.published));
CREATE INDEX resume_alias_search ON public.resume_title_aliases USING gin(to_tsvector('simple',alias));
CREATE TABLE public.resume_career_levels (id text PRIMARY KEY, label text NOT NULL, sort_order integer NOT NULL, published boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.resume_career_levels TO authenticated; GRANT ALL ON public.resume_career_levels TO service_role;
ALTER TABLE public.resume_career_levels ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_career_levels FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_occupation_levels (occupation_id text NOT NULL REFERENCES public.resume_occupations(id), level_id text NOT NULL REFERENCES public.resume_career_levels(id), PRIMARY KEY(occupation_id,level_id));
GRANT SELECT ON public.resume_occupation_levels TO authenticated; GRANT ALL ON public.resume_occupation_levels TO service_role;
ALTER TABLE public.resume_occupation_levels ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_occupation_levels FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.resume_occupations o WHERE o.id=occupation_id AND o.published));
CREATE TABLE public.resume_template_designs (id text PRIMARY KEY, label text NOT NULL, version integer NOT NULL DEFAULT 1, renderer_key text NOT NULL, definition jsonb NOT NULL, published boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.resume_template_designs TO authenticated; GRANT ALL ON public.resume_template_designs TO service_role;
ALTER TABLE public.resume_template_designs ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_template_designs FOR SELECT TO authenticated USING (published);
CREATE TABLE public.resume_template_assignments (id text PRIMARY KEY, occupation_id text NOT NULL REFERENCES public.resume_occupations(id), level_id text NOT NULL REFERENCES public.resume_career_levels(id), blueprint_id text NOT NULL REFERENCES public.resume_role_blueprints(id), design_id text NOT NULL REFERENCES public.resume_template_designs(id), title_id text REFERENCES public.resume_job_titles(id), published boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.resume_template_assignments TO authenticated; GRANT ALL ON public.resume_template_assignments TO service_role;
ALTER TABLE public.resume_template_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalogue_read ON public.resume_template_assignments FOR SELECT TO authenticated USING (published);
CREATE UNIQUE INDEX resume_assignment_unique ON public.resume_template_assignments(occupation_id,level_id,design_id,COALESCE(title_id,''));
CREATE TABLE public.resume_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, title_id text REFERENCES public.resume_job_titles(id), level_id text REFERENCES public.resume_career_levels(id), design_id text REFERENCES public.resume_template_designs(id), blueprint_id text REFERENCES public.resume_role_blueprints(id), design_version integer NOT NULL DEFAULT 1, blueprint_version integer NOT NULL DEFAULT 1, schema_version integer NOT NULL DEFAULT 2, document jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.resume_versions TO authenticated; GRANT ALL ON public.resume_versions TO service_role;
ALTER TABLE public.resume_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_select ON public.resume_versions FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY owner_insert ON public.resume_versions FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id);
CREATE POLICY owner_update ON public.resume_versions FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY owner_delete ON public.resume_versions FOR DELETE TO authenticated USING(auth.uid()=user_id);
CREATE INDEX resume_versions_owner ON public.resume_versions(user_id,updated_at DESC);
CREATE FUNCTION public.validate_resume_version() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF length(btrim(NEW.name))=0 OR length(NEW.name)>120 OR jsonb_typeof(NEW.document)<>'object' OR pg_column_size(NEW.document)>500000 OR jsonb_typeof(NEW.document->'content') IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.document->'sections') IS DISTINCT FROM 'array' OR jsonb_typeof(NEW.document->'settings') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid resume version'; END IF;
IF TG_OP='UPDATE' THEN IF NEW.user_id<>OLD.user_id OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Resume revision conflict'; END IF; NEW.created_at:=OLD.created_at; ELSE NEW.revision:=1; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_resume_version BEFORE INSERT OR UPDATE ON public.resume_versions FOR EACH ROW EXECUTE FUNCTION public.validate_resume_version();
CREATE FUNCTION public.search_resume_titles(p_search text DEFAULT '', p_industry text DEFAULT '', p_category text DEFAULT '', p_level text DEFAULT '', p_sort text DEFAULT 'popular', p_offset integer DEFAULT 0) RETURNS TABLE(id text,occupation_id text,title text,category_id text,industry_id text,popular_rank integer,total_count bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
SELECT t.id,t.occupation_id,t.title,t.category_id,t.industry_id,t.popular_rank,count(*) OVER() FROM public.resume_job_titles t WHERE t.published AND (p_industry='' OR t.industry_id=p_industry) AND (p_category='' OR t.category_id=p_category) AND (p_level='' OR EXISTS(SELECT 1 FROM public.resume_occupation_levels l WHERE l.occupation_id=t.occupation_id AND l.level_id=p_level)) AND (btrim(p_search)='' OR to_tsvector('simple',t.title) @@ plainto_tsquery('simple',left(p_search,200)) OR t.normalized_title LIKE '%'||lower(left(p_search,200))||'%' OR EXISTS(SELECT 1 FROM public.resume_title_aliases a WHERE a.title_id=t.id AND (to_tsvector('simple',a.alias) @@ plainto_tsquery('simple',left(p_search,200)) OR a.normalized_alias LIKE '%'||lower(left(p_search,200))||'%'))) ORDER BY CASE WHEN lower(t.title)=lower(p_search) THEN 0 ELSE 1 END,CASE WHEN p_sort='popular' THEN t.popular_rank END NULLS LAST,CASE WHEN p_sort='recent' THEN t.published_at END DESC,t.title LIMIT 24 OFFSET greatest(0,least(p_offset,100000)); $$;
REVOKE ALL ON FUNCTION public.search_resume_titles(text,text,text,text,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.search_resume_titles(text,text,text,text,text,integer) TO authenticated,service_role;